#!/usr/bin/env bash
# Prints Formula/lysosome.rb for a lysosome-dev/cli release.
#
#   render-formula.sh            # latest non-prerelease
#   render-formula.sh v0.1.0     # a specific tag
#
# Checksums come from the release's cargo-dist `sha256.sum` asset, so nothing
# large is downloaded. Needs: gh (authenticated via GH_TOKEN), curl, awk.
set -euo pipefail

REPO="${SOURCE_REPO:-lysosome-dev/cli}"
TAG="${1:-}"

if [ -z "$TAG" ]; then
  TAG="$(gh api "repos/$REPO/releases/latest" --jq .tag_name)"
fi
VERSION="${TAG#v}"
BASE="https://github.com/$REPO/releases/download/$TAG"

SUMS="$(curl -fsSL --retry 3 "$BASE/sha256.sum")"

sha() {
  local file="lysosome-$1.tar.xz" hash
  # sha256.sum lines look like "<hash>  <file>" or "<hash> *<file>".
  hash="$(printf '%s\n' "$SUMS" | awk -v f="$file" '{ n = $2; sub(/^\*/, "", n) } n == f { print $1 }')"
  if ! [[ "$hash" =~ ^[0-9a-f]{64}$ ]]; then
    echo "error: no sha256 for $file in $TAG/sha256.sum" >&2
    exit 1
  fi
  printf '%s' "$hash"
}

MAC_ARM="$(sha aarch64-apple-darwin)"
MAC_INTEL="$(sha x86_64-apple-darwin)"
LINUX_ARM="$(sha aarch64-unknown-linux-gnu)"
LINUX_INTEL="$(sha x86_64-unknown-linux-gnu)"

cat <<RUBY
# typed: false
# frozen_string_literal: true

# Generated by .github/workflows/update-formula.yml from the $TAG release of
# https://github.com/$REPO. Do not edit by hand.
class Lysosome < Formula
  desc "Find and safely reclaim the disk your dev tools and coding agents leave behind"
  homepage "https://lysosome.dev"
  version "$VERSION"
  license "MIT"

  on_macos do
    on_arm do
      url "$BASE/lysosome-aarch64-apple-darwin.tar.xz"
      sha256 "$MAC_ARM"
    end
    on_intel do
      url "$BASE/lysosome-x86_64-apple-darwin.tar.xz"
      sha256 "$MAC_INTEL"
    end
  end

  on_linux do
    on_arm do
      url "$BASE/lysosome-aarch64-unknown-linux-gnu.tar.xz"
      sha256 "$LINUX_ARM"
    end
    on_intel do
      url "$BASE/lysosome-x86_64-unknown-linux-gnu.tar.xz"
      sha256 "$LINUX_INTEL"
    end
  end

  def install
    bin.install "lysosome"
    man1.install Dir["man/*.1"]
    bash_completion.install "completions/lysosome.bash" => "lysosome" if File.exist?("completions/lysosome.bash")
    zsh_completion.install "completions/_lysosome" if File.exist?("completions/_lysosome")
    fish_completion.install "completions/lysosome.fish" if File.exist?("completions/lysosome.fish")
  end

  test do
    assert_match "lysosome #{version}", shell_output("#{bin}/lysosome --version")
    assert_match "#compdef lysosome", shell_output("#{bin}/lysosome completions zsh")
  end
end
RUBY
